from typing import TypedDict


class AgentState(TypedDict, total=False):
    # Original user request
    question: str

    # Planning
    subquestions: list[str]

    # Research
    evidence: list[dict]
    tool_calls: list[dict]

    # Answer generation and review
    draft_answer: str
    critique: str
    is_grounded: bool
    review_issues: list[str]
    revision_count: int

    # Final output
    final_answer: str
